import{_ as r,o as t,c as o,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"CQM 退相干：跨层级深耦合与唯一性难题","description":"","frontmatter":{},"headers":[],"relativePath":"D016_跨层级深耦合与唯一性难题.md","filePath":"D016_跨层级深耦合与唯一性难题.md"}'),n={name:"D016_跨层级深耦合与唯一性难题.md"};function s(l,a,i,p,_,h){return t(),o("div",null,[...a[0]||(a[0]=[e('<div><h1 id="cqm-退相干-跨层级深耦合与唯一性难题" tabindex="-1">CQM 退相干：跨层级深耦合与唯一性难题 <a class="header-anchor" href="#cqm-退相干-跨层级深耦合与唯一性难题" aria-label="Permalink to &quot;CQM 退相干：跨层级深耦合与唯一性难题&quot;">​</a></h1><p><strong>作者</strong>：ruster</p><h2 id="_1-唯一性难题" tabindex="-1">1. 唯一性难题 <a class="header-anchor" href="#_1-唯一性难题" aria-label="Permalink to &quot;1. 唯一性难题&quot;">​</a></h2><p>退相干理论——无论是引力参与的退相干、环境退相干还是其他形式的退相干——最终都会留下一个共同的难题：<strong>唯一性难题</strong>。</p><p>具体而言：当退相干完成后，我们得到的是经典概率分布，即多个可能状态各自带有概率权重。但为什么实际观察到的是<strong>这一个</strong>状态，而不是另一个状态？经典概率本身无法回答这个问题。</p><p>为了保幺正并同时试图解决唯一性难题，多世界理论以及类似理论就出现了。然而这些理论引入的多分支是冗余的、不可观测的，并且带有形而上学负担。更成问题的是，在其自然推论之下，<strong>能动性和实践变成了理论上可有可无的东西</strong>。虽然这些理论并不必然否定能动性，但要在其中承认能动性是一件困难的事情。</p><p>在 CQM 看来，这种困境的根源是<strong>层级还原论</strong>。</p><h2 id="_2-层级还原论的困境" tabindex="-1">2. 层级还原论的困境 <a class="header-anchor" href="#_2-层级还原论的困境" aria-label="Permalink to &quot;2. 层级还原论的困境&quot;">​</a></h2><p>层级还原论导致一个层级的有限因果链条无限上承：测量结果要还原到仪器状态，仪器状态要还原到量子系统，量子系统要还原到环境耦合，环境耦合又要还原到引力场……如此无限追溯，没有一个层级能够提供终止机制。</p><p>同时，由于层级还原论要求上层完全由下层决定，<strong>上层没有转折机制来确保唯一性保底</strong>。下层如果只给出经典概率分布，上层也只能继承这个概率分布，无法从中筛出单一事实。</p><p>因此，在层级还原论框架下，退相干机制无法真正推到底：它只能从叠加态退到经典概率，却无法从经典概率进一步到达确定结果。为了“保底”，多世界理论便引入无限平行的分支——用存在的冗余性来替代对唯一性的真正解释。</p><h2 id="_3-cqm-的跨层级退相干深耦合机制" tabindex="-1">3. CQM 的跨层级退相干深耦合机制 <a class="header-anchor" href="#_3-cqm-的跨层级退相干深耦合机制" aria-label="Permalink to &quot;3. CQM 的跨层级退相干深耦合机制&quot;">​</a></h2><p>CQM 提出一种<strong>“跨层级退相干深耦合”</strong>机制，在<strong>概念</strong>层面给出唯一性难题的机制，并将整个退相干过程统一起来；其在机制层面的严格化（『闭环相容子空间一维性猜想』）仍为开放问题（详见 <code>03 引力与退相干/CQM_退相干_引力因果场.md</code> §十-5、§十-7）。</p><p>在 CQM 中，退相干贯穿从叠加态到经典概率的全过程，解决唯一性（可能性空间压缩到唯一分支），但不解决确定性。确定性由再生产锁定。不需要中间引入多世界或别的什么诠释。</p><p>退相干深耦合与浅耦合没有本质区别，只是相对于从叠加到经典、以及从经典到确定做了一个区分。退相干本质上是一个连续谱。经典到确定也并不是说非要上层参与，<strong>重点是耦合是否足够深入，能筛出唯一值</strong>。</p><p>在 CQM 的引力（因果限制场）退相干理论下：</p><ul><li>引力耦合叠加态，使叠加态发生变化；</li><li>最终退相干留下经典概率；</li><li>而要得到确定结果，则需要再生产锁定——再生产闭环将唯一分支锁定为确定结果。</li></ul><p>人类在量子测量中的实践就属于这种过程——上层参与退相干深耦合。要得到确定结果，就需要更深的耦合，而不是等待确定性自动涌现。</p><h2 id="_4-基础层级是边界层、条件层和原料层-不是决定层" tabindex="-1">4. 基础层级是边界层、条件层和原料层，不是决定层 <a class="header-anchor" href="#_4-基础层级是边界层、条件层和原料层-不是决定层" aria-label="Permalink to &quot;4. 基础层级是边界层、条件层和原料层，不是决定层&quot;">​</a></h2><p>在 CQM 中，基础层级是<strong>边界层、条件层和原料层</strong>，而不是<strong>决定层</strong>。</p><ul><li><strong>边界层</strong>：为上层划定不可违背的边界；</li><li><strong>条件层</strong>：为上层提供存在和演化的可能性空间；</li><li><strong>原料层</strong>：为上层提供构成自身的质料和可能性素材。</li></ul><p>一般而言，不能从基础层决定上层的一切因果结构，甚至本体论结构。CQM 彻底反对层级还原论。对于上层而言，只要不违背基础层的条件，就能拥有相对独立的因果结构和本体论结构；其具体组织由上层自身的自组织机制和具体组织前提展开。</p><p>也就是说，上层可以有自己的相对独立的本体论结构和因果结构。这一点不需要 CQM 额外去保障——对于一个非还原的层级论而言，这是自然的推论。CQM 能进一步做的，是提供这一机制的细节。</p><h2 id="_5-能动性" tabindex="-1">5. 能动性 <a class="header-anchor" href="#_5-能动性" aria-label="Permalink to &quot;5. 能动性&quot;">​</a></h2><p>高层级可以具有能动性：能动地选择耦合方式以及耦合深度。</p><p>这使得能动性不再是无关紧要、可有可无的东西。相反，能动性对于组织事物是有用的——因为利用引力去退相干、去进行退相干深耦合，就是在建立与事物之间的因果联系。</p><p>CQM 明确：<strong>意识是物质发展到一定阶段的产物</strong>。在物理层级中，没有必要也不需要引入意识。能动性在这里是广义的组织因果联系的能力，不限于人类意识。</p><h2 id="_6-两种退相干深耦合现象" tabindex="-1">6. 两种退相干深耦合现象 <a class="header-anchor" href="#_6-两种退相干深耦合现象" aria-label="Permalink to &quot;6. 两种退相干深耦合现象&quot;">​</a></h2><p><strong>① 互耦退相干深耦合</strong></p><p>对于宏观时空，环境引力结构以及环境自举已经足够完成退相干深耦合。这种退相干深耦合与上层无关。</p><p><strong>② 情景退相干深耦合</strong></p><p>对于具体情景，当环境自举不足以筛出唯一值时，需要进一步退相干深耦合。上层能动系统可以选择更深的耦合方式，从而参与确定结果的产生。</p><h2 id="_7-物质内禀不确定性的层级表现" tabindex="-1">7. 物质内禀不确定性的层级表现 <a class="header-anchor" href="#_7-物质内禀不确定性的层级表现" aria-label="Permalink to &quot;7. 物质内禀不确定性的层级表现&quot;">​</a></h2><p>能动性、退相干后的经典概率以及叠加态，都是物质<strong>内禀不确定性</strong>的表现，只是不同层级的表现：</p><p>退相干后的经典概率可能来自热运动、信息不全面、或两者兼有。</p><ul><li>必然先在；</li><li>然后有必然的必然；</li><li>必然的偶然等价于偶然的必然；</li><li>但没有偶然的偶然。</li></ul><p>在不同的必然形式下，偶然的表现也会不同。</p></div>',1)])])}const c=r(n,[["render",s]]);export{g as __pageData,c as default};
